/*updateAgentConfirm1*/
	UPDATE	ICOMCMPY
	SET		STATUS = 'C',
			CONFIRM_DATE = NVL(CONFIRM_DATE, TO_CHAR(SYSDATE,'YYYYMMDD')),
			CONFIRM_TIME = NVL(CONFIRM_TIME, TO_CHAR(SYSDATE,'HH24MISS'))
	WHERE	COM_CODE = #{com_code}


/*updateAgentConfirm2*/
	UPDATE	ICOMLUSR
	SET		STATUS = 'C',
			CONFIRM_DATE = NVL(CONFIRM_DATE, TO_CHAR(SYSDATE,'YYYYMMDD')),
			CONFIRM_USER_ID = NVL(CONFIRM_USER_ID, (SELECT CONFIRM_USER_ID FROM ICOMCMPY WHERE COM_CODE = #{com_code})) 
	WHERE	COM_CODE = #{com_code}


/*updateAgentConfirm3*/
	UPDATE	SUPLINFO2
	SET		CONFIRM1_DATE = NVL(CONFIRM1_DATE, TO_CHAR(SYSDATE,'YYYYMMDD')),
			CONFIRM1_TIME = NVL(CONFIRM1_TIME, TO_CHAR(SYSDATE,'HH24MISS')),
			CONFIRM1_USER_ID = NVL(CONFIRM1_USER_ID, (SELECT CONFIRM_USER_ID FROM ICOMCMPY WHERE COM_CODE = #{com_code}))
	WHERE	SUPPLIER = #{com_code}


